-- v4.4.4 governed Portal Agent Pool, managed nodes, storage and endpoints.
DECLARE
  PROCEDURE ddl(s VARCHAR2) IS BEGIN EXECUTE IMMEDIATE s; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
BEGIN
  ddl('CREATE TABLE CX_PORTAL_LLM_POLICIES (POLICY_ID VARCHAR2(64) PRIMARY KEY,DEFAULT_PROFILE_ID VARCHAR2(128),VERSION NUMBER(19,0) DEFAULT 1 NOT NULL,UPDATED_BY VARCHAR2(128),REASON VARCHAR2(2000),UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_PORTAL_LLM_ALLOWLIST (POLICY_ID VARCHAR2(64) NOT NULL,PROFILE_ID VARCHAR2(128) NOT NULL,STATUS VARCHAR2(32) DEFAULT ''ACTIVE'' NOT NULL,UPDATED_BY VARCHAR2(128),REASON VARCHAR2(2000),UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT PK_CX_PORTAL_LLM_ALLOW PRIMARY KEY(POLICY_ID,PROFILE_ID))');
  ddl('CREATE TABLE CX_PLATFORM_ADMIN_COMMANDS (COMMAND_ID VARCHAR2(128) PRIMARY KEY,COMMAND_TYPE VARCHAR2(64) NOT NULL,TARGET_JSON CLOB NOT NULL,PARAMETERS_JSON CLOB NOT NULL,SECURITY_DOMAIN_ID VARCHAR2(128) NOT NULL,REQUESTED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(2000) NOT NULL,STATUS VARCHAR2(32) NOT NULL,EXPIRES_AT TIMESTAMP NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_MANAGED_NODES (NODE_ID VARCHAR2(128) PRIMARY KEY,NODE_KEY VARCHAR2(128) UNIQUE NOT NULL,HOST_REFERENCE VARCHAR2(256) NOT NULL,SSH_PORT NUMBER(10) DEFAULT 22 NOT NULL,OS_USER VARCHAR2(128),ROLE_JSON CLOB NOT NULL,FAILURE_DOMAIN VARCHAR2(128),TRUST_MODE VARCHAR2(32) NOT NULL,STATUS VARCHAR2(32) NOT NULL,VALIDATION_STATE VARCHAR2(32) NOT NULL,CREATED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(2000) NOT NULL,LAST_VALIDATED_AT TIMESTAMP,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_SHARED_STORAGE_PROFILES (STORAGE_ID VARCHAR2(128) PRIMARY KEY,STORAGE_KEY VARCHAR2(128) UNIQUE NOT NULL,BACKEND_KIND VARCHAR2(32) NOT NULL,LOCATION_REF VARCHAR2(512) NOT NULL,STATUS VARCHAR2(32) NOT NULL,VALIDATION_STATE VARCHAR2(32) NOT NULL,CREATED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(2000) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_EXTERNAL_DB_ENDPOINTS (ENDPOINT_ID VARCHAR2(128) PRIMARY KEY,ENDPOINT_KEY VARCHAR2(128) UNIQUE NOT NULL,DATABASE_DIALECT VARCHAR2(32) NOT NULL,HOST_REFERENCE VARCHAR2(256) NOT NULL,PORT NUMBER(10) NOT NULL,TLS_REQUIRED VARCHAR2(1) DEFAULT ''Y'' NOT NULL,STATUS VARCHAR2(32) NOT NULL,CREATED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(2000) NOT NULL,CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)');
  ddl('CREATE INDEX IDX_CX_ADMIN_COMMAND_STATUS ON CX_PLATFORM_ADMIN_COMMANDS(STATUS,CREATED_AT)');
  ddl('CREATE INDEX IDX_CX_MANAGED_NODE_ROLE ON CX_MANAGED_NODES(STATUS,VALIDATION_STATE)');
END;
/
MERGE INTO CX_PORTAL_LLM_POLICIES d USING (SELECT 'DEFAULT' POLICY_ID FROM DUAL) s ON (d.POLICY_ID=s.POLICY_ID)
WHEN NOT MATCHED THEN INSERT(POLICY_ID,VERSION,UPDATED_BY,REASON) VALUES('DEFAULT',1,'SYSTEM','v4.4.4 Portal Agent Pool default policy');
MERGE INTO CX_AGENT_TEMPLATES d USING (SELECT 'CODE_PLAN' TEMPLATE_KEY FROM DUAL) s ON (d.TEMPLATE_KEY=s.TEMPLATE_KEY) WHEN NOT MATCHED THEN INSERT(TEMPLATE_ID,TEMPLATE_KEY,DISPLAY_NAME,TEMPLATE_KIND,CONTENT_JSON,CONTENT_DIGEST,LOCKED_FIELDS_JSON,STATUS,MANAGED,CREATED_BY) VALUES('TPL_CODE_PLAN','CODE_PLAN','Code Planning Agent','BUSINESS','{"skills":["task-plan","specs"],"classification":"INTERNAL"}','v4.4.4-code-plan','["skills","classification"]','PUBLISHED','Y','SYSTEM');
MERGE INTO CX_AGENT_TEMPLATES d USING (SELECT 'CODE_PROGRAM' TEMPLATE_KEY FROM DUAL) s ON (d.TEMPLATE_KEY=s.TEMPLATE_KEY) WHEN NOT MATCHED THEN INSERT(TEMPLATE_ID,TEMPLATE_KEY,DISPLAY_NAME,TEMPLATE_KIND,CONTENT_JSON,CONTENT_DIGEST,LOCKED_FIELDS_JSON,STATUS,MANAGED,CREATED_BY) VALUES('TPL_CODE_PROGRAM','CODE_PROGRAM','Code Programming Agent','BUSINESS','{"skills":["scm","task-plan"],"isolation":"DEDICATED_WORKSPACE"}','v4.4.4-code-program','["skills","isolation"]','PUBLISHED','Y','SYSTEM');
MERGE INTO CX_AGENT_TEMPLATES d USING (SELECT 'CODE_REVIEW' TEMPLATE_KEY FROM DUAL) s ON (d.TEMPLATE_KEY=s.TEMPLATE_KEY) WHEN NOT MATCHED THEN INSERT(TEMPLATE_ID,TEMPLATE_KEY,DISPLAY_NAME,TEMPLATE_KIND,CONTENT_JSON,CONTENT_DIGEST,LOCKED_FIELDS_JSON,STATUS,MANAGED,CREATED_BY) VALUES('TPL_CODE_REVIEW','CODE_REVIEW','Code Review Agent','BUSINESS','{"skills":["scm","audit"],"read_only":true}','v4.4.4-code-review','["skills","read_only"]','PUBLISHED','Y','SYSTEM');
MERGE INTO CX_AGENT_TEMPLATES d USING (SELECT 'OFFICE_TEXT' TEMPLATE_KEY FROM DUAL) s ON (d.TEMPLATE_KEY=s.TEMPLATE_KEY) WHEN NOT MATCHED THEN INSERT(TEMPLATE_ID,TEMPLATE_KEY,DISPLAY_NAME,TEMPLATE_KIND,CONTENT_JSON,CONTENT_DIGEST,LOCKED_FIELDS_JSON,STATUS,MANAGED,CREATED_BY) VALUES('TPL_OFFICE_TEXT','OFFICE_TEXT','Office Text Agent','BUSINESS','{"skills":["office-text"]}','v4.4.4-office-text','["skills"]','PUBLISHED','Y','SYSTEM');
MERGE INTO CX_AGENT_TEMPLATES d USING (SELECT 'PPT_DESIGN' TEMPLATE_KEY FROM DUAL) s ON (d.TEMPLATE_KEY=s.TEMPLATE_KEY) WHEN NOT MATCHED THEN INSERT(TEMPLATE_ID,TEMPLATE_KEY,DISPLAY_NAME,TEMPLATE_KIND,CONTENT_JSON,CONTENT_DIGEST,LOCKED_FIELDS_JSON,STATUS,MANAGED,CREATED_BY) VALUES('TPL_PPT_DESIGN','PPT_DESIGN','Presentation Design Agent','BUSINESS','{"skills":["office-text","ppt"]}','v4.4.4-ppt-design','["skills"]','PUBLISHED','Y','SYSTEM');
